// Mapbox GL JS (v5) default import – no longer works with MapLibre GL JS v6
// import mapboxgl from 'mapbox-gl';

// ✅ MapLibre GL JS v6 – namespace or named import (no default export)
import * as maplibregl from 'maplibre-gl';          // gives you the full namespace
