  zoom: 2
});
```

### Supplying a missing icon at runtime in MapLibre GL JS v6+

When a style references an `icon-image` name that isn’t present in the sprite sheet, MapLibre now emits a **`styleimagemissing`** event **only as a notification**.  
The old pattern of calling `map.addImage()` inside that handler no longer resolves the request.

Instead you register a **missing-style-image resolver** with `map.setMissingStyleImageResolver()`.  
The resolver is called with the missing image id; you fetch or generate the image and add it to the map yourself. As soon as `map.addImage()` finishes, the style will be re-evaluated and the icon will appear.

```js
// Create the map (any options you need)
import * as maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';

const map = new maplibregl.Map({
  container: 'map',
  style: 'https://example.com/your-style.json',
  center: [0, 0],
  zoom: 2,
});

/**
 * Helper – turn a URL or a Blob into an ImageBitmap that MapLibre can use.
 * You can also draw on a canvas and return the canvas directly.
 */
async function loadImageBitmap(src) {
  const response = await fetch(src);
  const blob = await response.blob();
  return await createImageBitmap(blob);
}

/**
 * Register the resolver **once** (before the style finishes loading).
 * It can be async; MapLibre will wait for the promise to settle.
 */
map.setMissingStyleImageResolver(async (missingId) => {
  // --------------------------------------------------------------
  // 1️⃣ Decide how you want to obtain the image.
  // --------------------------------------------------------------
  // Example A – fetch a PNG from a known URL pattern:
  // const url = `https://my.cdn.com/icons/${missingId}.png`;

  // Example B – generate a canvas-based icon on the fly:
  // const canvas = document.createElement('canvas');
  // canvas.width = canvas.height = 64;
  // const ctx = canvas.getContext('2d');
  // ctx.fillStyle = '#ff6600';
  // ctx.beginPath(); ctx.arc(32, 32, 30, 0, Math.PI * 2); ctx.fill();
  // const imageBitmap = await createImageBitmap(canvas);

  // --------------------------------------------------------------
  // 2️⃣ Load / create the image bitmap.
  // --------------------------------------------------------------
  const url = `https://my.cdn.com/icons/${missingId}.png`;
  const imageBitmap = await loadImageBitmap(url);

  // --------------------------------------------------------------
  // 3️⃣ Add the image to the map.
  // --------------------------------------------------------------
  // The third argument (`options`) is optional – you can set
  // `sdf`, `pixelRatio`, `stretchX/Y`, etc. if you need them.
  map.addImage(missingId, imageBitmap, { sdf: false });

  // --------------------------------------------------------------
  // 4️⃣ (Optional) Return a value – MapLibre ignores it.
  // --------------------------------------------------------------
  // return true;
});
```

#### How it works

| Step | What happens |
|------|--------------|
| **`styleimagemissing` fires** | MapLibre detects that the style needs an image that isn’t in the sprite. |
| **Resolver called** | `setMissingStyleImageResolver` receives the missing image’s **id**. |
| **You fetch / generate the image** | Any async method works (fetch, canvas drawing, WebGL rendering, etc.). |
| **`map.addImage(id, bitmap, options)`** | Registers the image under the same id that the style asked for. |
| **Map re-evaluates the style** | The newly added image is now available and the corresponding symbols appear. |

#### Common variations

* **Generating icons on the fly** – instead of fetching a PNG, draw on a `<canvas>` (or use an SVG → `ImageBitmap`) and pass the resulting bitmap to `addImage`.
* **SDF (signed-distance-field) icons** – set `{sdf: true}` if you need color-tinting via `icon-color`.
* **Multiple resolutions** – you can provide a `pixelRatio` option if you serve `@2x` assets.
* **Caching** – the resolver may be called repeatedly for the same id (e.g., if the style reloads). Keep a simple `Map` of already-added ids to avoid duplicate network requests.

#### Why the old `styleimagemissing` handler no longer works

In v5 the handler could *resolve* the request by calling `addImage` synchronously.  
In v6 `styleimagemissing` is **notify-only**; MapLibre does **not** wait for any side-effects. The new resolver API is the only way to tell the library “I’m providing the missing image now”.

#### When to call `setMissingStyleImageResolver`

* **Before** the map’s style finishes loading (i.e., right after you create the `Map` instance).  
* You can call it later, but any symbols that were already rendered will stay missing until the style reloads or you manually trigger a refresh (`map.triggerRepaint()`).

#### Full minimal example (HTML)

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>Dynamic missing icons</title>
  <link href="https://unpkg.com/maplibre-gl@^6/dist/maplibre-gl.css" rel="stylesheet" />
  <style>
    #map { position: absolute; top:0; bottom:0; width:100%; }
  </style>
</head>
<body>
<div id="map"></div>

<script type="module">
  import * as maplibregl from 'https://unpkg.com/maplibre-gl@^6/dist/maplibre-gl.mjs';

  const map = new maplibregl.Map({
    container: 'map',
    style: 'https://example.com/style-with-missing-icons.json',
    center: [0, 0],
    zoom: 2,
  });

  // Resolver – fetch PNGs from a CDN pattern
  map.setMissingStyleImageResolver(async (id) => {
    const url = `https://my.cdn.com/icons/${id}.png`;
    const resp = await fetch(url);
    if (!resp.ok) {
      console.warn(`Icon "${id}" not found at ${url}`);
      return;
    }
    const blob = await resp.blob();
    const bitmap = await createImageBitmap(blob);
    map.addImage(id, bitmap);
  });
</script>
</body>
</html>
```

Now any feature that uses `icon-image: "my-dynamic-icon"` (where `"my-dynamic-icon"` isn’t in the sprite) will automatically trigger the resolver, fetch the PNG, add it to the map, and appear on the map without a page reload.

Below is a **v6-compatible** way to read every piece of the camera state that the public API exposes, plus the only place you can get the **projection matrix** (the combined view-projection matrix that MapLibre builds for WebGL rendering).

---

## 1️⃣  Public camera getters (center, zoom, bearing, pitch)

```js
// ESM import – v6 has no default export
import * as maplibregl from 'maplibregl';

// create the map as usual
const map = new maplibregl.Map({
  container: 'map',
  style: 'https://demotiles.maplibre.org/style.json',
  center: [0, 0],
  zoom: 2,
  pitch: 45,
  bearing: 30
});

// Anywhere after the map is loaded you can read the state:
function logCameraState() {
  const center = map.getCenter();          // → LngLat object
  const zoom   = map.getZoom();            // → number
  const bearing = map.getBearing();        // → number (degrees)
  const pitch   = map.getPitch();          // → number (degrees)

  console.log('center', center.toArray());
  console.log('zoom',   zoom);
  console.log('bearing', bearing);
  console.log('pitch',   pitch);
}

// Example: log on every move end
map.on('moveend', logCameraState);
```

All of the above works **without touching any private property** (e.g. `map.transform` no longer exists in v6).

---

## 2️⃣  Getting the projection matrix

The projection matrix is **not exposed through a public getter**.  
The only supported entry point is the `render` callback of a **custom layer**.  
MapLibre passes the matrix (a `Float32Array` of 16 numbers, column-major) as the second argument to `render`.

```js
// 1️⃣  Define a custom layer that just captures the matrix
const matrixCaptureLayer = {
  id: 'matrix-capture',
  type: 'custom',
  // Called once when the layer is added to the map
  onAdd: function (map, gl) {
    // you can keep a reference to the map or GL context if you need it later
    this.map = map;
    this.gl = gl;
  },

  // Called on every frame that the map renders
  render: function (gl, matrix) {
    // `matrix` is a Float32Array[16] = projection * view matrix
    // Store it where you need it (e.g. a global variable, a class field, etc.)
    this.lastMatrix = new Float32Array(matrix); // copy if you’ll use it later

    // OPTIONAL: draw something with the matrix – here we just clear the screen
    // gl.clearColor(0, 0, 0, 0);
    // gl.clear(gl.COLOR_BUFFER_BIT);
  }
};

// 2️⃣  Add the layer (it will start receiving render calls)
map.addLayer(matrixCaptureLayer);

// 3️⃣  Helper to read the latest matrix whenever you want
function getProjectionMatrix() {
  // `matrixCaptureLayer.lastMatrix` will be undefined until the first render
  return matrixCaptureLayer.lastMatrix ?? null;
}

// Example: log the matrix after the first render
map.once('render', () => {
  console.log('Projection-view matrix:', getProjectionMatrix());
});
```

### What the matrix represents
* **Column-major 4 × 4 matrix** (`Float32Array[16]`).
* It combines the **camera view** (center, zoom, bearing, pitch) and the **projection** (Web Mercator or any custom projection you set via `map.setProjection()`).
* You can feed it directly into any WebGL shader that expects a `mat4` uniform, or unpack it in JavaScript for custom math (e.g. converting world coordinates → screen coordinates).

---

## 3️⃣  Putting it all together – a tiny utility class

If you need the full state (center, zoom, bearing, pitch, matrix) in one place, you can wrap the above pattern:

```js
class CameraState {
  constructor(map) {
    this.map = map;

    // Install the custom layer that will keep the matrix up-to-date
    const layer = {
      id: 'camera-state-matrix',
      type: 'custom',
      onAdd: (map, gl) => { this.gl = gl; },
      render: (gl, matrix) => { this.matrix = new Float32Array(matrix); }
    };
    map.addLayer(layer);
  }

  // Public getters
  get center()   { return this.map.getCenter(); }
  get zoom()     { return this.map.getZoom(); }
  get bearing()  { return this.map.getBearing(); }
  get pitch()    { return this.map.getPitch(); }
  get matrix()   { return this.matrix ?? null; }   // may be null before first render
}

// Usage
const cam = new CameraState(map);

// Whenever you need the state:
function doMyMath() {
  const center  = cam.center.toArray();   // [lng, lat]
  const zoom    = cam.zoom;
  const bearing = cam.bearing;
  const pitch   = cam.pitch;
  const matrix  = cam.matrix;            // Float32Array[16] or null

  // …your custom calculations here…
}
map.on('moveend', doMyMath);
```

---

## 4️⃣  Quick checklist (v5 → v6 migration points)

| What you tried in v5 | What you must change for v6 |
|----------------------|----------------------------|
| `map.transform.center` / `map.transform.zoom` | Use `map.getCenter()`, `map.getZoom()`, `map.getBearing()`, `map.getPitch()` |
| Accessing the matrix via `map.transform` | Use a **custom layer** and read the `matrix` argument of its `render` method |
| `import maplibregl from 'maplibre-gl'` | `import * as maplibregl from 'maplibre-gl'` (or named imports) |
| CDN `<script src="…/dist/maplibre-gl.js">` | `<script type="module"> import … from '…/dist/maplibre-gl.mjs'; </script>` |
| `require('maplibre-gl')` in Node | Convert the file to ESM or `await import('maplibre-gl')` |

---

### TL;DR

* **Center / zoom / bearing / pitch** → `map.getCenter()`, `map.getZoom()`, `map.getBearing()`, `map.getPitch()`.
* **Projection matrix** → only available inside a **custom layer**’s `render(gl, matrix)` callback; store the `matrix` yourself if you need it later.
* No more `map.transform` – the public getters are the supported way.

Feel free to adapt the utility class above to your app’s architecture; it gives you a single source of truth for all camera-related data while staying fully compatible with MapLibre GL JS v6.

```ts
import type {
  Map,
  MapSourceDataEvent,
  MapStyleDataEvent,
} from 'maplibre-gl';

// The map instance you already created
declare const map: Map;

// Helper type-guard – narrows a generic data event to a source-data event
function isSourceDataEvent(
  e: MapSourceDataEvent | MapStyleDataEvent,
): e is MapSourceDataEvent {
  return 'sourceDataType' in e;
}

// Attach the handler
map.on('data', (e: MapSourceDataEvent | MapStyleDataEvent) => {
  if (!isSourceDataEvent(e)) {
    // This is a style-data event – ignore or handle separately
    // e.type === 'style'  (or other style-specific properties)
    return;
  }

  // At this point `e` is a MapSourceDataEvent, so `sourceDataType` is safe to use
  switch (e.sourceDataType) {
    case 'metadata':
      console.log('Source metadata loaded', e.sourceId);
      break;

    case 'source':
      console.log('Source data (tiles, geojson, …) loaded', e.sourceId);
      break;

    case 'visibility':
      console.log('Source visibility changed', e.sourceId);
      break;

    // Add any other sourceDataType values you care about
    default:
      console.warn('Unhandled sourceDataType', e.sourceDataType);
  }
});
```

**Explanation**

* `MapSourceDataEvent` and `MapStyleDataEvent` are the two event types emitted by the `'data'` event in MapLibre GL JS v6.  
* The `isSourceDataEvent` type-guard checks for the presence of `sourceDataType`, which only exists on `MapSourceDataEvent`.  
* Inside the `if (isSourceDataEvent(e))` block the compiler knows `e` is a `MapSourceDataEvent`, so you can safely narrow on `e.sourceDataType` and access other source-specific fields (`sourceId`, `tile`, …).  

This handler is fully type-safe under TypeScript ≥ 4.5 and works with the v6-only ESM build of MapLibre GL JS.

Below is a minimal, **v6-compatible** Vite + TypeScript setup that shows everything you need to get a MapLibre GL JS map on the page:

```ts
/* src/main.ts ----------------------------------------------------------- */
import { Map, setWorkerUrl } from 'maplibre-gl';          // ← named import, no default export
import 'maplibre-gl/dist/maplibre-gl.css';               // ← bring the default stylesheet in
import workerUrl from 'maplibre-gl/dist/maplibre-gl-worker.mjs?worker&url'; // ← Vite worker helper

// Tell MapLibre where the Web-Worker file lives (required for bundlers)
setWorkerUrl(workerUrl);

// Wait until the <div id="map"> element exists (Vite mounts the app after DOM load)
document.addEventListener('DOMContentLoaded', () => {
  const map = new Map({
    container: 'map',                     // id of the div in index.html
    style: 'https://demotiles.maplibre.org/style.json', // any valid style URL
    center: [0, 0],                       // [lng, lat]
    zoom: 2,
    // any other Map options you need …
  });

  // Example of using the public Camera API (map.transform no longer exists)
  console.log('zoom →', map.getZoom());
  console.log('center →', map.getCenter().toArray());

  // Optional: add a control so you can zoom/pan with the UI
  import { NavigationControl } from 'maplibre-gl';
  map.addControl(new NavigationControl(), 'top-right');
});
```

```html
<!-- public/index.html ---------------------------------------------------- -->
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Vite + MapLibre GL JS</title>
  <style>
    /* Make the map fill the viewport */
    html, body, #map { margin:0; padding:0; height:100%; width:100%; }
  </style>
</head>
<body>
  <div id="map"></div>
  <script type="module" src="/src/main.ts"></script>
</body>
</html>
```

### What the pieces do

| Piece | Why it’s needed for v6 |
|------|------------------------|
| `import { Map, setWorkerUrl } from 'maplibre-gl'` | v6 removed the default export; you must use a **named** or **namespace** import. |
| `import 'maplibre-gl/dist/maplibre-gl.css'` | The CSS is no longer bundled automatically; you have to import it yourself (Vite will bundle it). |
| `import workerUrl … ?worker&url` | In a bundler environment the worker can’t be auto-discovered via `import.meta.url`. `setWorkerUrl()` tells MapLibre where the worker file lives. The `?worker&url` query is the Vite-recommended way (it creates a separate worker chunk and gives you its URL). |
| `setWorkerUrl(workerUrl)` | Must be called **once**, before any `new Map()` is constructed. |
| `map.getZoom()`, `map.getCenter()` … | `map.transform` was removed in v6. Use the public Camera getters (`getZoom`, `getBearing`, `getPitch`, `getCenter`, etc.). |
| `NavigationControl` (optional) | Demonstrates that you can still import other classes the same way. |

### Vite config (optional)

If you’re using Vite ≥ 4 the default config works out-of-the-box.  
Only if you have a custom `vite.config.ts` that changes the handling of workers you might need to ensure the `worker` plugin is enabled (it is by default).

```ts
// vite.config.ts (only needed for special cases)
import { defineConfig } from 'vite';
export default defineConfig({
  // …your custom config
});
```

### Quick checklist after installing

```bash
npm i maplibre-gl@^6   # pin to the v6 major (or a specific patch)
npm i -D vite typescript @types/maplibre-gl   # dev deps for the build
```

Now run the dev server:

```bash
npm run dev   # (or whatever script you defined for Vite)
```

You should see a fully functional MapLibre map, and the console will show the current zoom/center values without any `ERR_PACKAGE_PATH_NOT_EXPORTED` or blank-map errors.

Below is a **complete, minimal example** that shows how to

1. load a **PMTiles** file (a single-file container for vector tiles) with the official `pmtiles` library,  
2. add it to a **MapLibre GL JS v6** map as a vector source, and  
3. draw a simple **line layer** from one of the source’s layers.

The code works both in a plain HTML page (CDN) and in a bundler-based project (Vite, webpack, etc.).  
Only the parts that differ between the two environments are highlighted.

---

## 1️⃣ Install the packages (bundler projects)

```bash
npm i maplibre-gl@^6 pmtiles
# If you use a bundler you’ll also need the CSS:
npm i -D style-loader css-loader   # for webpack, Vite already handles CSS
```

> **Note:** MapLibre v6 is **ESM-only** – there is no default export.  
> Use a namespace import (`import * as maplibregl …`) or named imports (`{Map, NavigationControl}`).

---

## 2️⃣ HTML-only (CDN) version

If you don’t use a bundler you can copy-paste the following into a single HTML file.  
Everything is loaded as ES modules, so the `<script>` tag must have `type="module"`.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>PMTiles + MapLibre GL JS v6</title>
  <style>
    body, html { margin:0; height:100%; }
    #map { width:100%; height:100%; }
  </style>
  <!-- MapLibre GL CSS -->
  <link href="https://unpkg.com/maplibre-gl@^6/dist/maplibre-gl.css" rel="stylesheet">
</head>
<body>
<div id="map"></div>

<script type="module">
  // ---- 1️⃣ Import the libraries -------------------------------------------------
  import * as maplibregl from 'https://unpkg.com/maplibre-gl@^6/dist/maplibre-gl.mjs';
  import { PMTiles } from 'https://cdn.jsdelivr.net/npm/pmtiles@latest/dist/index.mjs';

  // ---- 2️⃣ Register the PMTiles protocol ---------------------------------------
  // The PMTiles library works by installing a custom fetch handler for URLs
  // that start with the "pmtiles://" scheme.
  const pmtilesUrl = 'https://YOUR_DOMAIN/path/to/tiles.pmtiles'; // <-- change this
  const pm = new PMTiles(pmtilesUrl);
  // The library automatically registers the protocol when you call `register()`.
  // (If you use the CDN build you can just call `pm.register()`.)
  pm.register();   // now `pmtiles://...` URLs are understood by fetch()

  // ---- 3️⃣ Create the map -------------------------------------------------------
  const map = new maplibregl.Map({
    container: 'map',
    style: {
      version: 8,
      sources: {},          // we’ll add our source later
      layers: []            // we’ll add our layer later
    },
    center: [0, 0],
    zoom: 2
  });

  // ---- 4️⃣ Add the PMTiles vector source ---------------------------------------
  // The URL we give to the source must use the custom scheme that the library
  // registered above. The part after `pmtiles://` can be any identifier you like.
  map.once('load', () => {
    map.addSource('my-pmtiles-source', {
      type: 'vector',
      // The protocol handler will translate this to a fetch of the .pmtiles file.
      url: 'pmtiles://my-pmtiles'   // <-- identifier, can be anything
    });

    // ---- 5️⃣ Add a line layer -------------------------------------------------
    // Replace `my_layer_name` with the actual layer name that lives inside the
    // vector tiles (you can inspect it with `mapbox-gl-inspect` or by opening the
    // .pmtiles file with `pmtiles inspect`).
    map.addLayer({
      id: 'my-lines',
      type: 'line',
      source: 'my-pmtiles-source',
      'source-layer': 'my_layer_name',   // <-- the name of the vector-tile layer
      paint: {
        'line-color': '#ff6600',
        'line-width': 2
      }
    });
  });
</script>
</body>
</html>
```

**What’s happening?**

| Step | Explanation |
|------|-------------|
| **Import** | Pulls the ESM builds of MapLibre GL JS and the `pmtiles` helper. |
| **`pm.register()`** | Installs a fetch interceptor that rewrites `pmtiles://…` URLs to HTTP requests that read the single-file container. |
| **`map.addSource`** | Declares a normal *vector* source, but the URL uses the custom scheme. |
| **`map.addLayer`** | Draws a line from the vector-tile layer named `my_layer_name`. |

---

## 3️⃣ Bundler version (Vite / webpack / esbuild / Rollup)

Below is a **TypeScript** (or plain JavaScript) module you can drop into `src/main.ts` (or `index.js`) of a Vite project. The same pattern works for webpack, esbuild, etc.; you only need to adjust the `setWorkerUrl()` call for your bundler (see the migration guide if you’re on v6).

```ts
// src/main.ts ---------------------------------------------------------------
import 'maplibre-gl/dist/maplibre-gl.css';               // MapLibre CSS
import { Map, setWorkerUrl } from 'maplibre-gl';
import { PMTiles } from 'pmtiles';

// ---------------------------------------------------------------
// 1️⃣ Tell MapLibre where its worker lives (required for bundlers)
// ---------------------------------------------------------------
import workerUrl from 'maplibre-gl/dist/maplibre-gl-worker.mjs?worker&url';
setWorkerUrl(workerUrl);

// ---------------------------------------------------------------
// 2️⃣ Register the PMTiles protocol
// ---------------------------------------------------------------
const pmtilesUrl = 'https://YOUR_DOMAIN/path/to/tiles.pmtiles'; // <-- change
const pm = new PMTiles(pmtilesUrl);
pm.register();   // registers the `pmtiles://` fetch handler

// ---------------------------------------------------------------
// 3️⃣ Initialise the map
// ---------------------------------------------------------------
const map = new Map({
  container: 'map',               // <div id="map"></div> must exist in index.html
  style: {
    version: 8,
    sources: {},                  // we’ll add the source later
    layers: []                    // we’ll add the layer later
  },
  center: [0, 0],
  zoom: 2
});

// ---------------------------------------------------------------
// 4️⃣ Add the vector source and line layer once the style is loaded
// ---------------------------------------------------------------
map.once('load', () => {
  // ---- vector source -------------------------------------------------
  map.addSource('my-pmtiles-source', {
    type: 'vector',
    url: 'pmtiles://my-pmtiles'   // identifier – can be any string
  });

  // ---- line layer ----------------------------------------------------
  map.addLayer({
    id: 'my-lines',
    type: 'line',
    source: 'my-pmtiles-source',
    // The name of the layer inside the vector tiles. You can discover it
    // with `pmtiles inspect <file>` or by looking at the source’s metadata.
    'source-layer': 'my_layer_name',
    paint: {
      'line-color': '#ff6600',
      'line-width': 2
    }
  });
});
```

**HTML entry point (`index.html`)**

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>PMTiles + MapLibre (Vite)</title>
  <style>
    html, body, #map { margin:0; height:100%; width:100%; }
  </style>
</head>
<body>
  <div id="map"></div>
  <script type="module" src="/src/main.ts"></script>
</body>
</html>
```

### What you need to adapt

| Placeholder | What to replace |
|-------------|-----------------|
| `https://YOUR_DOMAIN/path/to/tiles.pmtiles` | URL of your own PMTiles file (can be on a CDN, S3, etc.). |
| `'my_layer_name'` | The **source-layer** name inside the vector tiles that contains the line features you want to render. |
| Paint properties (`line-color`, `line-width`) | Any styling you prefer (you can also add `line-opacity`, `line-dasharray`, etc.). |

---

## 4️⃣ Quick sanity-check checklist

| ✅ | Checklist item |
|---|-----------------|
| **PMTiles library loaded** | `import { PMTiles } …` and `pm.register()` executed before the source is added. |
| **Custom protocol used** | Source URL starts with `pmtiles://`. |
| **Correct source-layer name** | Verify with `pmtiles inspect <file>` or by loading the tiles in a viewer (e.g., MapLibre GL JS dev tools). |
| **Worker URL set (bundler only)** | `setWorkerUrl(workerUrl)` called **once** before creating the `Map`. |
| **MapLibre CSS imported** | `import 'maplibre-gl/dist/maplibre-gl.css'` (or a `<link>` tag). |
| **Map container exists** | `<div id="map"></div>` in the HTML. |

If any of those steps is missing you’ll see one of the following typical symptoms:

| Symptom | Likely cause |
|---------|--------------|
| Blank map, console error `Failed to load worker` | `setWorkerUrl()` not called (bundler) |
| `Error: Invalid source: url must be a string` | Source URL not using the `pmtiles://` scheme or `pm.register()` not called |
| No lines appear, but the map renders | Wrong `source-layer` name or the layer in the tiles is not a line type |
| `NetworkError when attempting to fetch resource` | The PMTiles URL is unreachable or CORS-blocked |

---

## 5️⃣ Optional: Styling a **dynamic** line based on feature properties

If your vector tiles contain a property (e.g., `class` or `type`) you can style each line differently using an **expression**:

```ts
map.addLayer({
  id: 'my-lines',
  type: 'line',
  source: 'my-pmtiles-source',
  'source-layer': 'my_layer_name',
  paint: {
    // Color based on a feature property called "class"
    'line-color': [
      'match',
      ['get', 'class'],
      'highway', '#ff0000',
      'primary', '#ff6600',
      /* default */ '#999999'
    ],
    'line-width': [
      'interpolate',
      ['linear'],
      ['zoom'],
      5, 1,
      12, 4,
      16, 8
    ]
  }
});
```

---

## 6️⃣ TL;DR – One-liner summary

```js
import * as maplibregl from 'maplibre-gl';
import { PMTiles } from 'pmtiles';
new PMTiles('https://example.com/tiles.pmtiles').register();

const map = new maplibregl.Map({container:'map',style:{version:8,sources:{},layers:[]},center:[0,0],zoom:2});
map.once('load', () => {
  map.addSource('pmtiles', {type:'vector', url:'pmtiles://my-pmtiles'});
  map.addLayer({id:'lines',type:'line',source:'pmtiles','source-layer':'my_layer_name',
                paint:{'line-color':'#ff6600','line-width':2}});
});
```

That’s it—your PMTiles vector data is now driving a line layer on a MapLibre GL JS v6 map! 🎉
